def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        if '+' in core:
            core, _ = core.split('+', 1)
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return major, minor, patch, pre_ids

    def cmp_id(a, b):
        a_num = a.isdigit()
        b_num = b.isdigit()
        if a_num and b_num:
            an, bn = int(a), int(b)
            return (an > bn) - (an < bn)
        if a_num and not b_num:
            return -1
        if not a_num and b_num:
            return 1
        return (a > b) - (a < b)

    def cmp_pre(p1, p2):
        if p1 is None and p2 is None:
            return 0
        if p1 is None:
            return 1
        if p2 is None:
            return -1
        for i in range(min(len(p1), len(p2))):
            c = cmp_id(p1[i], p2[i])
            if c != 0:
                return c
        return (len(p1) > len(p2)) - (len(p1) < len(p2))

    def cmp_ver(v1, v2):
        p1 = parse(v1)
        p2 = parse(v2)
        for i in range(3):
            if p1[i] != p2[i]:
                return -1 if p1[i] < p2[i] else 1
        return cmp_pre(p1[3], p2[3])

    import functools
    return sorted(versions, key=functools.cmp_to_key(cmp_ver))

